package ru.murad.yourmarket.service;import org.junit.jupiter.api.Test;import ru.murad.yourmarket.config.TelegramProperties;import static org.mockito.Mockito.*;
class RateLimitCleanupSchedulerTest {@Test void cleanupIsBoundedWhenEveryBatchIsFull(){RateLimitService service=mock(RateLimitService.class);when(service.cleanupExpired()).thenReturn(500);TelegramProperties properties=new TelegramProperties(new TelegramProperties.Bot("b","t"),new TelegramProperties.Channel("c","c","u"),new TelegramProperties.Payment("p"),new TelegramProperties.Moderation(""),new TelegramProperties.Admin(java.util.List.of()),new TelegramProperties.RateLimit(true,20,60,24,500,3));new RateLimitCleanupScheduler(service,properties).cleanup();verify(service,times(3)).cleanupExpired();}}
